window.TEXTP["9.52"] = [{"n":1066,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":46.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["c","человека и становится обязательным при наличии возможности."],["h","<b>• ВОПРОС № 13: ШАРИАТСКОЕ ПОЛОЖЕНИЕ ПРИНЯТИЯ ПРИГЛАШЕНИЯ НА СВАДЬБУ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Принятие приглашения на свадебное угощение является обязательным».</i>",{"mt":0.34}],["p","Исходя из хадиса, приводимого в обоих Сахихах и других сборниках со слов Абу Хурайры, который сказал: <i>«Худшее угощение — это свадебное угощение, на которое приглашают богатых и оставляют бедных. А тот, кто не ответил на приглашение, ослушался Аллаха и Его посланника»<sup>35</sup>.</i>"],["p","Также в обоих Сахихах приводится хадис со слов Ибн ‘Умара о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Если вас пригласили, отвечайте на это приглашение»<sup>36</sup>.</i></b>"],["p","А в другой версии этого хадиса говорится: <b><i>«Если кого-либо из вас позовут на свадебное угощение, пусть пойдёт»<sup>37</sup>.</i></b>"],["p","А ещё в одной версии, приводимой у Муслима (1432) и у других, говорится: <b><i>«Кто был приглашён и не ответил, тот ослушался Аллаха и Его посланника».</i></b>"],["p","Также у Муслима (1430–105) и у других приводится хадис со слов Джабира о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Если одного из вас пригласят на угощение, пусть ответит. А затем, если пожелает, может поесть, а если нет, может оставить».</i></b>"],["p","Ещё в одной версии этого хадиса, приводимой у Муслима (1431– 106) и у других со слов Абу Хурайры, сообщается, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Если кого-либо из вас пригласят, пусть ответит на приглашение. Если при этом он держит пост, пусть помолится (за пригласивших его), если же он не постится, то пусть поест».</i></b>"]],"notes":[[35,"Аль-Бухари (5177), Муслим (1432)."],[36,"Аль-Бухари (5179), Муслим (1429–103)."],[37,"Аль-Бухари (5173), Муслим (1429–96)."]]},{"n":1067,"head":"КНИГА 16. ЖЕРТВОПРИНОШЕНИЕ И УГОЩЕНИЕ","side":"r","blocks":[["p","Ибн ‘Абду ль-Барр, аль-Кады ‘Ияд и ан-Навави привели единогласное мнение учёных об обязательности принятия приглашения на свадебное угощение."],["p","Хафиз Ибн Хаджар в «аль-Фатх» (9/272) сказал: <i>«Однако это не совсем так. Да, от учёных известно и распространено об обязательности этого и большинство шафи‘итов и ханбалитов на мнении, что это является индивидуальной обязанностью каждого приглашённого, и то же самое говорил Малик. Однако некоторые шафи‘иты и ханбалиты всё же считали это желательным».</i>"],["p","Аль-Махди в «аль-Бахр» передал, что «аль-‘итра»<sup>38</sup> и аш-Шафи‘и считали принятие приглашения на свадебное угощение желательным, таким же, как и принятие приглашения по любому другому поводу."],["p","Однако приведённые доводы всё же указывают на обязательность, тем более после того как пророк (да благословит его Аллах и приветствует) известил о том, что человек, не ответивший на приглашение, ослушался Аллаха и Его посланника."],["p","Смысл хадисов с велением принятия приглашения на свадебное угощение подразумевает истинный смысл, указывающий на обязательность, однако обусловленную отсутствием чего-либо, препятствующего этому, как наличие порицаемых вещей, хвастовства и соперничества, приглашение на угощение одних лишь богатых, и тому подобного."],["p","И до нас не дошло никаких текстов, уводящих эти приказы от их истинного смысла, указывающего на обязательность."],["p","А что касается принятия приглашения помимо приглашения на свадебное угощение, то в отношении этого учёные разошлись во мнениях, является ли оно обязательным или нет?"],["p","Те учёные, кто склонился к обязательности, аргументировали своё мнение вышеприведёнными хадисами с обобщённым смыслом, в которых нет конкретизации именно свадебным угощением."],["p","Другие же конкретизировали обобщённые тексты хадисами, в которых говорится именно о свадебном угощении."]],"notes":[[38,"Под «аль-‘итра» он имеет в виду ‘Али, Фатыму и их потомков."]]},{"n":1068,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":46.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","Всё это автор (аш-Шаукани) подробно разъяснил в «Шарху ль-Мунтака» с указанием на правильное мнение в этом вопросе."],["p","Абу Мухаммад аль-Багави в «Шарху с-Сунна» (9/141) сказал: <i>«Тот, у кого есть оправдание, или же путь далёк и сложен, то нет проблем в том, чтобы человек не ответил на приглашение».</i>"],["p","Уалию-Ллах ад-Дахляуи в «аль-Мусаува шарх аль-Муватта» (2/126) сказал: <i>«Автор книги «аль-Ануар» говорит: «Из условий обязательности, чтобы приглашение на свадебное угощение стало обязательным то, чтобы оно исходило либо от родственников, либо от соседей, либо от коллег, когда приглашение охватывает и богатых, и бедных. Если же приглашаются лишь богатые, то обязательность принятия приглашения спадает. Но если он позвал своих коллег, которыми являются богатые, тогда они обязаны ответить на приглашение». Однако это обусловливание для того, чтобы принятие приглашения стало обязательным, неправильно, так как смысл слов Абу Хурайры в утверждении скверности угощения объясняет лишь одну из его сторон. Вместе с тем также утверждается и грех человека, отказавшегося от приглашения. Исходя из этого, будет правильным считать, что приглашение только богатых порицаемо сугубо для самого приглашающего, однако это не мешает распространению на других обязательности принятия приглашения».</i>"],["h","<b>• ВОПРОС № 14: ЧЬЁ ПРИГЛАШЕНИЕ ПРИНЯТЬ, ЕСЛИ ПРИГЛАСИВШИХ ДВОЕ?</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Предпочтение в принятии приглашение отдаётся тому, кто позвал первым, затем тому, чья дверь ближе».</i>",{"mt":0.34}],["p","Исходя из хадиса, приводимого Хумайдом ибн ‘Абду р-Рахманом аль-Химьяри со слов одного из сподвижников о том, что пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Если человека одновременно позвали двое, то пусть примет приглашение того, чья дверь ближе, так как ближе дверью — ближе соседством. Если же один из пригласивших опередил другого, то принимается приглашение того, кто был первым»<sup>39</sup>.</i></b>"]],"notes":[[39,"Слабый хадис. См. «аль-Ирва» (1951)."]]},{"n":1069,"head":"КНИГА 16. ЖЕРТВОПРИНОШЕНИЕ И УГОЩЕНИЕ","side":"r","frames":[{"s":"a","h":46.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","Хадис привели Ахмад (23513) и Абу Дауд (3756) с иснадом, в котором присутствует Зайд ибн ‘Абду р-Рахман ад-Даляни, которого посчитал надёжным Абу Хатим, а Ибн Хиббан считал его слабым передатчиком."],["p","Также аль-Бухари (6020) и другие привели хадис со слов ‘Аиши о том, что, когда она спросила посланника Аллаха (да благословит его Аллах и приветствует) о том, кому из двух соседей ей сделать подарок, он ответил: <b><i>«Тому, чья дверь ближе».</i></b> Из этого понимается, что в подобных вопросах может учитываться фактор близости двери."],["h","<b>• ВОПРОС № 15: УСЛОВИЯ, ПРИ КОТОРЫХ ПРИНЯТИЕ ПРИГЛАШЕНИЯ СТАНОВИТСЯ ОБЯЗАТЕЛЬНЫМ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«И не дозволено посещение свадебного угощения, если оно содержит что-либо греховное».</i>",{"mt":0.34}],["p","Исходя из хадиса, который приводит Ибн Маджа (3359) с иснадом, передатчики которого являются передатчиками достоверных хадисов. В нём говорится, что ‘Али сказал: <i>«Как-то я приготовил пищу и позвал посланника Аллаха (да благословит его Аллах и приветствует). Но, придя ко мне домой и увидев изображения живых существ, он ушёл»<sup>40</sup>.</i>"],["p","Абу Дауд (3774), ан-Насаи (4/16) и аль-Хаким (4/129) привели хадис со слов Ибн ‘Умара, который сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) запретил два вида приёма пищи: присутствие за столом, на котором присутствует алкоголь, и то, чтобы человек принимал пищу, распластавшись на животе».</i> Однако иснад хадиса нецелостный<sup>41</sup>."],["p","Также запрет сидения за столом, на котором присутствует алкоголь, содержится в хадисе со слабым иснадом, который привёл Ахмад (1/20) со слов ‘Умара<sup>42</sup>."]],"notes":[[40,"См. «Сахих ан-Насаи» (5366), «Сахих Ибн Маджа» (2724)."],[41,"Слабый хадис. См. «аль-Ирва» (1982)."],[42,"Несмотря на слабость именно этой версии хадиса, он подкрепляется другими версиями и похожими по смыслу хадисами, вследствие чего данный хадис можно считать достоверным. См. «ат-Та‘ликату р-радыййа» (3/142)."]]},{"n":1070,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.48,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","А также подобный хадис слов Джабира приводит ат-Тирмизи (2801), посчитав его приемлемым (хасан). Также подобное сообщение привели Ахмад (3/339), ан-Насаи (4/171), ат-Тирмизи и аль-Хаким (4/288) со слов Джабира, передавшего это от пророка (да благословит его Аллах и приветствует)."],["p","В данной главе есть и другие доводы, а также это подтверждается текстами, пришедшими относительно призыва к одобряемому и запрещения порицаемого<sup>43</sup>."],["p","Из их числа хадис: <b><i>«Кто увидит порицаемое, пусть исправит это рукой, если не может рукой, то пусть исправит это словом, а если не может и словом, то пусть порицает это своим сердцем»<sup>44</sup></i></b>. Этот хадис приводится в обоих Сахихах<sup>45</sup> и других сборниках."],["h","<b>• ВОПРОС № 16: ′АКЫКА<sup>46</sup></b>",{"mt":0.3,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«‘Акыка является желательным».</i>",{"mt":0.33}],["p","Исходя из хадиса, приводимого у аль-Бухари (5471, 5472) и у других со слов Сальмана ибн ‘Амира ад-Дабби о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«С рождением</i></b>"]],"notes":[[43,"Также в числе причин, снимающих обязанность, учёные упоминают и другие вещи. Так, хафиз ан-Навави в «Минхаджу т-талибин» говорит: <i>«А что касается оправданий, по причине которых спадает обязательность ответа на приглашение, то из них: если в пище есть сомнения или приглашены только богатые, или там будет присутствовать человек, с которым неприятно находится в одном месте, или если человека пригласили, опасаясь его зла или из-за его почётного положения, или для того, чтобы он помог во зле; а также если на этом собрании будет присутствовать алкоголь, или придётся сидеть на шёлковых покрывалах, или если присутствуют изображения живых существ, или если придётся есть и пить из серебряной или золотой посуды. Всё это является оправданием, по причине которого спадает обязанность принятия приглашения на свадебное угощение. Также из оправданий, по причине которых можно отказаться от приглашения, это если позвал кто-либо из людей Писания, так как не является обязательным отвечать на его призыв».</i>"],[44,"Муслим (49)."],[45,"Хадис не приводится у аль-Бухари, а только у Муслима и у авторов «ас-Сунан»."],[46,"‘Акыка — это жертвоприношение, совершаемое на седьмой день после рождения ребёнка, в знак благодарности Всевышнему Аллаху за оказанную милость. См. «аль-Мугни» (9/458), «аль-Маджму’» (8/426), «Нейль аль-аутар» (5/149)."]]},{"n":1071,"head":"КНИГА 16. ЖЕРТВОПРИНОШЕНИЕ И УГОЩЕНИЕ","side":"r","blocks":[["c","<b> <i>мальчика должна быть совершена ‘акыка. Принесите за него жертвоприношение и избавьте младенца от страданий (бритьём головы)».</i></b>"],["p","Ахмад и авторы сборников «ас-Сунан» привели хадис, который назвали достоверным ат-Тирмизи, аль-Хаким и ‘Абду ль-Хакк. В нём аль-Хасан передаёт со слов Самуры о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Каждый ребёнок является заложником своей ‘акыки, за него режут животное на седьмой день, и в тот же день ему дают имя и бреют голову»<sup>47</sup>.</i></b>"],["p","Есть мнение, что за исключением этого хадиса, аль-Хасан не слышал хадисы непосредственно от Самуры."],["p","Ахмад (6713), Абу Дауд (2842) и ан-Насаи (4212) привели хадис со слов ‘Амра ибн Шу‘айба от его отца, со слов его деда, который сказал: <i>«Когда посланник Аллаха (да благословит его Аллах и приветствует) был спрошен об ‘акыке, он сказал:</i> <b><i>«Мне не нравится ослушание (аль-‘укук)»,</i></b> <i>— словно ему не понравилось название. Люди сказали: «Поистине, мы лишь спрашиваем о том, когда у одного из нас рождается ребёнок». Тогда он ответил:</i> <b><i>«Кто желает зарезать за новорожденного, пусть сделает это. За мальчика двух равноценных баранов, а за девочку одного»».</i></b>"],["p","Этот хадис является доводом на то, что хадисы, в которых говорилось о том, что каждый ребёнок является заложником своей ‘акыки, не указывают на обязательность ‘акыки, однако её совершение является желательным."],["p","Ведь если бы совершение ‘акыки было обязательным, то людям не предоставлялся бы выбор словами: <b><i>«Кто желает зарезать за новорожденного…».</i></b>"],["p","И тогда правильным пониманием других слов пророка (да благословит его Аллах и приветствует): <b><i>«является заложником своей ‘акыки»,</i></b> — является то, что ‘акыка является следствием рождения так же, как залог является следствием долга."],["p","Есть также мнение, что под этим имеется в виду то, что ребёнку не дают имя и не бреют его голову, пока не зарежут барана. Про это ясно говорили авторы трудов «аль-Машарик» и «ан-Нихая»."]],"notes":[[47,"Ахмад (20151), Абу Дауд (2837), ат-Тирмизи (1522), ан-Насаи (4220), Ибн Маджа (3165)."]]},{"n":1072,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":46.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","Ахмад ибн Ханбаль считал, что смысл этих слов заключается в том, что если ребёнок, за которого не сделают ‘акыку, умрёт в младенчестве, то он не будет заступаться за своих родителей."],["p","Тем не менее, большинство обладателей знания считало ‘акыку желательной, кроме Абу Ханифы, который не считал её даже Сунной."],["h","<b>• ВОПРОС № 17: ЧТО РЕЖУТ ПРИ РОЖДЕНИИ МАЛЬЧИКА И ЧТО ПРИ РОЖДЕНИИ ДЕВОЧКИ?</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«За мальчика режут двух баранов, а за девочку одного».</i>",{"mt":0.34}],["p","Как это передается аш-Шафи‘и, исходя из приводимого ранее хадиса со слов деда ‘Амра ибн Шу‘айба, а также исходя из хадиса, приводимого у Ахмада (6/31), ат-Тирмизи (1513), Ибн Хиббана (7/356) и аль-Байхакы (9/301), и который приемлемым (хасан) посчитал ат-Тирмизи. В нём со слов ‘Аиши сообщается о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«За мальчика режут двух равноценных баранов, а за девочку одного».</i></b>"],["p","Подобный хадис со слов Умм Курз аль-Ка‘бия привели Ахмад (6/381), ан-Насаи (7/165), ат-Тирмизи (1516), аль-Хаким (4/237) и ад-Даракутни (4/586), а ат-Тирмизи назвал его приемлемым (хасан)."],["p","Под равноценностью в хадисе имеется в виду либо то, чтобы они либо были одинаковыми, либо схожими."],["p","Абу Дауд (2841) и ан-Насаи (7/166) привели хадис, который назвал достоверным ‘Абду ль-Хакк и Ибн Дакык аль-‘Ийд. В нём со слов Ибн ‘Аббаса сообщается, что посланник Аллаха (да благословит его Аллах и приветствует) резал по одному барану за аль-Хасана и аль-Хусайна<sup>48</sup>."]],"notes":[[48,"Учёные разошлись относительно достоверности данной версии хадиса, поскольку в другой версии, которую приводит ан-Насаи (4219), и достоверность которой подтвердил шейх аль-Альбани, говорится, что пророк (да благословит его Аллах и приветствует) зарезал по два барана за каждого из них. Однако достоверность упомянутой версии подтвердили имамы Ибн Хузайма, Ибн аль-Джаруд, ‘Абду ль-Хакк аль-Ишбили, Ибн Дакык аль-‘Ид, Ибн ‘Абду ль-Хади, а также и шейх аль-Альбани. Это также подтверждается тем, что передаётся от сподвижников. Так, Ибн ‘Умар приносил в жертву за своих детей, как мальчиков, так и девочек по одному барану. Также подобным образом поступал и ‘Урва ибн аз-Зубайр, который приносил за своих детей обоих полов по одному барану. См. «аль-Муватта» (2/401) имама Малика и «ас-Сунан аль-кубра» (9/302) имама аль-Байхакы. Шу’айб аль-Арнаут подтвердил достоверность иснадов обоих сообщений. Хафиз ан-Навави сказал: <i>«Сунной является принести в жертву за мальчика двух баранов, а за девочку одного. Однако если за мальчика зарезали одно животное, то и это соответствует Сунне».</i> См. «аль-Маджму’» (8/429)."]]},{"n":1073,"head":"КНИГА 16. ЖЕРТВОПРИНОШЕНИЕ И УГОЩЕНИЕ","side":"r","blocks":[["p","Однако этот хадис не противоречит вышеприведённым по той причине, что в них содержится то же, что содержится в этом хадисе, плюс дополнительно присутствует ещё что-то. В дополнение к этому, предыдущие хадисы содержали словесное обращение к исламской общине, а, как известно из науки «усулю ль-фикх», действия пророка (да благословит его Аллах и приветствует) не противопоставляются его словам, обращённым к общине мусульман."],["p","Дополнение приемлемо только в том случае, если оно не отменяет другое, поэтому желающий зарезать за мальчика барана не поступит в соответствии с Сунной, кроме как если зарежет двух баранов, а не одного."],["p","Относительно новорожденной девочки учёные единогласны в том, что за неё режут одного барана. А насчёт мальчика большинство учёных считало необходимым резать двух баранов, а Малик говорил, что достаточно и одного."],["p","Шамсуддин Мухаммад аль-Махалли сказал: <i>«Начальное соответствие Сунне происходит, если при ‘акыке за мальчика режут одного барана, однако полноценное соответствие Сунне происходит, если режут двух баранов».</i>"],["p","Аш-Шафи‘и сказал: <i>«С мясом ‘акыки в отношении его употребления и раздачи в виде милостыни поступают так же, как и с мясом жертвоприношения (удхия). И желательно приготовить его, не ломая костей».</i>"],["p","Я заявляю, что нет никакого довода ни из Корана, ни из Сунны, ни даже со стороны разума на эту желательность сохранения целыми костей барана, а также и на нежелательность расчленения суставов и всех остальных костей, на необходимость их последующего закапывания и тому подобного. Однако всё это предрассудки, схожие с тем, что распространяют женщины и другие из числа рядовых мусульман"]],"notes":[]},{"n":1074,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":28.9,"mt":0.71,"pb":0.48,"ml":-3,"mr":-3,"pl":8,"pr":8},{"s":"a","h":46.9,"mt":0.71,"pb":0.48,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["c",". В выполнении всего этого нет абсолютно никакой пользы ни для этого мира, ни для мира вечного."],["h","<b>• ВОПРОС № 18: ВРЕМЯ СОВЕРШЕНИЯ ‘АКЫКИ</b>",{"mt":0.3,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«На седьмой день от рождения».</i>",{"mt":0.34}],["p","Исходя из приводимого ранее хадиса со слов Самуры."],["p","Необходимо, чтобы между рождением и ‘акыкой прошло какое-то время, в течение которого семья занята ребёнком и его матерью. Поэтому на людей не возлагается то, что лишь увеличит их занятость."],["p","Другая причина заключается в том, что не все люди могут сразу найти барана для ‘акыки, и, если бы Шариат возложил на человека ‘акыку в первый же день от рождения ребёнка, это стало бы обременительным. А семь дней — это как раз тот период, который подходит для всего этого и, вместе с тем, не является большим сроком."],["h","<b>• ВОПРОС № 19: КОГДА РЕБЁНКУ ДАЁТСЯ ИМЯ, И КАКИЕ ИМЕНА НАИБОЛЕЕ ЛЮБИМЫ ДЛЯ АЛЛАХА</b>",{"mt":0.3,"fr":2}],["p","[Сказал аш-Шаукани]: <i>«Также на седьмой день ему даётся имя».</i>",{"mt":0.34}],["p","А наиболее любимыми для Аллаха именами являются ‘Абду-Ллах (раб Аллаха) и ‘Абду р-Рахман (раб Милостивого), как об этом говорится в хадисе<sup>49</sup>, а также потому, что это наиболее известные из имён Аллаха и ими не называется никто, кроме Всевышнего Аллаха, в отличие от других Его имён<sup>50</sup>."]],"notes":[[49,"Посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Самые любимые имена для Аллаха — это ‘Абду-Ллах и ‘Абду р-Рахман».</i> </b>Муслим (2132). Имам Ибн Хазм сказал: <i>«Учёные единогласны в желательности имён, которые причисляются к Аллаху, как ‘Абду-Ллах, ‘Абду р-Рахман и подобные им».</i> См. «Маратибу ль-иджма’» (154). Также желательно называть детей именами пророков, да пребудет мир над ними. Что же касается известного хадиса: <i>«Нарекайте детей своих именами пророков»</i>, то он является слабым. См. «аль-Вахм ва ль-ихам» (4/379), «Ирвау ль-галиль» (1178). Но, несмотря на это, о желательности называть детей именами пророков есть другие достоверные указания. Так, имам аль-Бухари в своём сборнике «ас-Сахих» назвал главу следующим образом: <i>«Глава о том, кто давал детям имена пророков»</i>, после чего привёл в этой главе соответствующие хадисы."],[50,"Имеется в виду, что некоторыми из имён Аллаха можно называть людей без добавки перед ними слова «раб», так как эти качества в той или иной степени могут быть присуще людям, как например, Рахим, Хаким, Халим, Малик и др. А есть имена, описание которых не присуще никому, кроме одного Аллаха, как, например, ар-Рахман, ас-Самад, аль-Ахад и др."]]},{"n":1075,"head":"КНИГА 16. ЖЕРТВОПРИНОШЕНИЕ И УГОЩЕНИЕ","side":"r","frames":[{"s":"a","h":46.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8},{"s":"a","h":46.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","И в этом же кроется секрет желательности называть ребёнка также такими именами, как Мухаммад и Ахмад."],["p","Некоторые из людей испытывают страсть к тому, чтобы называть своих детей именами своих предков, которых они возвеличивают. И в этом усматривается как указание на их религию, так и на то, что он находится в связи с ними."],["p","Наиболее же правдивыми именами (соответствующими сущности человека) являются имена: Хаммам (желающий, суетливый) и Харис (пахарь). А наиболее скверным для человека является имя Малику ль-‘амляк (царь царей)."],["h","<b>• ВОПРОС № 20: ВРЕМЯ БРИТЬЯ ГОЛОВЫ И ПРОИЗНЕСЕНИЯ АЗАНА В УХО НОВОРОЖДЕННОГО</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«И в этот же день бреют его голову».</i>",{"mt":0.34}],["p","Удаление волос делает его похожим на паломника."],["p","Также посланник Аллаха (да благословит его Аллах и приветствует) произнёс слова азана в ухо аль-Хасана сына ‘Али, когда его родила Фатыма<sup>51</sup>. Смысл этого в том, что азан относится к внешним проявлениям Ислама и является его символом."],["p","Также из особенностей азана — это то, что шайтан убегает, заслышав его. А ведь известно, что шайтан досаждает новорождённому в начале его становления. И даже пришло в хадисе, что первый его плач является следствием этого<sup>52</sup>."],["h","<b>• ВОПРОС № 21: МИЛОСТЫНЯ НА ВЕС ВОЛОС РЕБЁНКА ЗОЛОТОМ ИЛИ СЕРЕБРОМ</b>",{"mt":0.31,"fr":2}],["p","[Сказал аш-Шаукани]: <i>«И дают милостыню золотом или серебром на вес сбритых волос».</i>",{"mt":0.34}]],"notes":[[51,"Слабый хадис. См. «ас-Сильсиля д-да‘ифа» (321)."],[52,"Хадис приводится у аль-Бухари (4274)."]]},{"n":1076,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","blocks":[["p","Исходя из веления пророка (да благословит его Аллах и приветствует) Фатыме, чтобы она сбрила волосы аль-Хасана и дала милостыню на вес сбритых волос серебром<sup>53</sup>. Хадис привели Ахмад (6/390) и аль-Байхакы (9/304), однако в его иснаде присутствует Ибн ‘Акыль, надёжность которого, как передатчика, под вопросом<sup>54</sup>."],["p","Данное положение также подтверждается сообщением, которое передали Малик (2/501) и Абу Дауд в «аль-Марасиль» (406) со слов Джа‘фара ибн Мухаммада, а аль-Байхакы (9/304) привёл это сообщение с добавкой, что Джа‘фар ибн Мухаммад передал от своего отца, а тот от деда, который сказал: <i>«Фатыма взвешивала волосы аль-Хасана, аль-Хусайна, Зайнаб и Умм Кульсум, и раздавала милостыню на вес их волос серебром».</i>"],["p","Также ат-Тирмизи (1519) и аль-Хаким (7589) привели хадис со слов ‘Али, который сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) совершил ‘акыку за аль-Хасана, зарезав барана, а затем сказал:</i> <b><i>«О Фатыма, побрей его голову и дай милостыню на вес его волос серебром»</i></b><i>. И мы взвесили его волосы, и они были равны дирхаму или части дирхама»<sup>55</sup>.</i>"],["p","Ат-Табарани в «аль-Авсат» (562) привёл хадис со слов Ибн ‘Аббаса, который сказал: <i>«Семь вещей являются Сунной в отношении ребёнка на седьмой день: ему даётся имя, делается обрезание, бреют его голову, прокалывают уши, режут барана, бреют голову и мажут его кровью барана, зарезанного на ‘акыку, и дают на вес его волос милостыню золотом или серебром».</i> В иснаде этого сообщения присутствует Раувад ибн Джаррах, который является слабым передатчиком, тогда как остальные передатчики этого сообщения являются надёжными<sup>56</sup>."]],"notes":[[53,"Хадис передаётся со слов ‘Али ибн Аби Талиба, который сказал: <i>«Когда посланник Аллаха (да благословит его Аллах и приветствует) совершил ‘акыку за аль-Хасана, он сказал:</i> <b><i>«О Фатыма, побрей его голову и раздай милостыню равную весу его волос».</i></b> <i>И она взвесила их, и их вес соответствовал дирхаму или части дирхама».</i> Ат-Тирмизи (1519), аль-Хаким (4/234)."],[54,"Шейх аль-Альбани сказал: <i>«Среди учёных он известен тем, что его хадисы являются приемлемыми “хасан”, кроме как в случае, если они противоречат другим достоверным хадисам. Однако этот хадис, наоборот, подтверждается другими, по причине чего его степень поднимается до уровня достоверного “сахих”».</i> См. «ат-Та‘ликату р-радыййа» (3/147)."],[55,"Хадис хороший (хасан). См. «аль-Ирва» (1175)."],[56,"Слабый хадис. См. «Фатху ль-Бари» (9/483)."]]},{"n":1077,"head":"КНИГА 16. ЖЕРТВОПРИНОШЕНИЕ И УГОЩЕНИЕ","side":"r","blocks":[["p","Однако в этих словах есть то, что является порицаемым, а именно то, что прокалывают ухо и обмазывают голову ребёнка кровью барана, зарезанного на ‘акыку."],["p","Абу Дауд (2843) и ан-Насаи привели хадис с достоверным иснадом со слов Бурайды аль-Аслями, который сказал: <i>«Во времена доисламской джахилии, если у одного из нас рождался сын, мы резали барана и мазали голову ребёнка его кровью. Когда же Аллах привёл нас к Исламу, мы резали барана, брили голову младенца и мазали его голову шафраном»<sup>57</sup>.</i>"],["p","Подобный же хадис со слов ‘Аиши привели Ибн Хиббан (7/355) и Ибн ас-Сакан и назвали его достоверным."],["p","Захириты и аль-Хасан аль-Басри склонились к тому, что совершение ‘акыки является обязательным. Большинство же учёных считало это желательным (сунной). А Абу Ханифа не относил ‘акыку ни к категории обязательного, ни желательного. Также от него передаётся, что он считал это добровольным действием."]],"notes":[[57,"Хадис достоверный. См. «ат-Та‘ликату р-радыййа» (3/148)."]]},{"front":true,"blocks":[["f","Книга 17",{"a":"c","z":40,"mt":332.3}],["f","<b>МЕДЕЦИНА</b>",{"a":"c","z":55,"mt":-6}],["img","",{"src":"img/pg-9-orn.webp","w":68,"h":27,"mt":1.59}]],"notes":[]},{"n":1081,"head":"КНИГА 17. МЕДИЦИНА","side":"r","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.48,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["h","КНИГА 17. МЕДИЦИНА",{"z":1.43}],["p","Суть медицины заключается в обнаружении исцеляющих природных свойств животного и растительного происхождения, а также минералов, и в создании растворов путём их смешивания в тех или иных пропорциях."],["p","А религиозные постулаты исключают из неё примеси многобожия и очищают от всего того, что может причинить вред как с бытовой, так и религиозной стороны, дабы медицина содержала в себе лишь пользу для всех людей."],["h","<b>• ВОПРОС № 1: УЗАКОНЕННОСТЬ ЛЕЧЕНИЯ</b>",{"mt":0.3,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Лечение дозволено».</i>",{"mt":0.34}],["p","Исходя из хадиса, который привели Муслим (2204) и другие со слов Джабира о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«От каждой болезни есть соответствующее лекарство, посредством которого с соизволения Аллаха приходит излечение».</i></b>"],["p","Аль-Бухари (5678) и другие привели хадис со слов Абу Хурайры о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Нет такой болезни, вместе с которой Аллах не ниспослал бы и её излечение».</i></b>"],["p","Ахмад (4/278), Абу Дауд (3855), Ибн Маджа (6061) и ат-Тирмизи (2038) привели хадис, достоверность которого наряду с ат-Тирмизи подтвердили также Ибн Хузайма и аль-Хаким (4/199). В нём со слов Усамы сообщается, что группа бедуинов обратилась к пророку (да благословит его Аллах и приветствует) со словами: <i>«О, посланник Аллаха, стоит ли нам лечиться?»,</i> — он сказал: <b><i>«Да, о, рабы Аллаха, лечитесь, ведь, поистине, Аллах не создал ни одной болезни, кроме как создал и лекарство от неё, за исключением одной единственной болезни».</i></b> Они спросили: <i>«Что же это, о, посланник Аллаха?»,</i> — на что он ответил: <b><i>«Старость».</i></b>"],["p","Ахмад (3/421), Ибн Маджа (3437) и ат-Тирмизи (2148), подтвердивший его достоверность, привели хадис со слов Абу Хузамы<sup>1</sup> о том,"]],"notes":[[1,"Абу Хузама относится к таби‘инам. По этой причине данный хадис является слабым. См. «ат-Та‘ликату р-радыййа» (3/152), однако есть другие похо- жие хадисы с таким же смыслом, имеющие другие цепочки передатчиков, что в совокупности возводит хадис до приемлемого «хасан», о чем сказал аль-Альбани в «Тахриджу ахадис Мушкиляту ль-факр» (стр. 11)."]]},{"n":1082,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":46.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["c","что он обратился к пророку (да благословит его Аллах и приветствует) со словами: <i>«О посланник Аллаха, что ты скажешь относительно заговоров, которые мы произносим, лекарств, которыми лечимся и средств защиты, которые используем? Разве они могут изменить что-либо из предопределения Аллаха?».</i> На это посланник Аллаха (да благословит его Аллах и приветствует) ответил: <b><i>«Они тоже входят в предопределение Аллаха».</i></b>"],["p","Данное положение разделяют все мусульмане, и не видят никаких проблем во всём этом."],["h","<b>• ВОПРОС № 2: ЧТО ЛУЧШЕ: ЛЕЧЕНИЕ ИЛИ ОТКАЗ ОТ НЕГО С ПРОЯВЛЕНИЕМ ТЕРПЕНИЯ?</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Отказ от лечения предпочтительнее и лучше для того, кто способен на проявление терпения».</i>",{"mt":0.34}],["p","Исходя из хадиса, приводимого в обоих Сахихах и других сборниках со слов Ибн ‘Аббаса о том, что однажды к пророку (да благословит его Аллах и приветствует) подошла чернокожая женщина и сказала: <i>«Поистине, я больна эпилепсией и, поистине, во время припадков случается так, что я раскрываюсь. Обратись же к Аллаху с мольбой о моём исцелении».</i> Пророк (да благословит его Аллах и приветствует) сказал: <b><i>«Если хочешь, прояви терпение, и тебе уготован Рай, а если хочешь, я попрошу Аллаха, чтобы Он исцелил тебя»,</i></b> — и она ответила: <i>«Тогда я буду терпеть. Однако во время припадка я раскрываюсь, попроси же Аллаха, чтобы я не раскрывалась»,</i> — и он обратился к Аллаху с мольбой, чтобы она не раскрывалась<sup>2</sup>."],["p","Также в обоих Сахихах приводится хадис со слов Ибн ‘Аббаса о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Семьдесят тысяч из моей общины войдут в Рай без расчёта. Это те, которые не просили прочесть им заклинание, не верили в приметы, не прижигали рану, и при этом они уповали на своего Господа»<sup>3</sup>.</i></b>"]],"notes":[[2,"Аль-Бухари (5652), Муслим (2576)."],[3,"Аль-Бухари (5705, 6472), Муслим (218, 220)."]]},{"n":1083,"head":"КНИГА 17. МЕДИЦИНА","side":"r","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","Данное положение никак не противоречит приводимым ранее хадисам с повелением лечиться, так как оставление лечения лучше лишь в отношении того, кто способен должным образом терпеть это, как на это указывают слова пророка (да благословит его Аллах и приветствует), сказанные чернокожей женщине: <b><i>«Если хочешь, прояви терпение…».</i></b>"],["p","Однако при отсутствии должного терпения перед болезнью или при доведении ситуации до крайности, приводящей к непосильным трудностям, к раздражению и стеснению груди от болезни, то в этом случае лечение лучше, так как достоинство пренебрежения лечением аннулируется отсутствием должного терпения."],["h","<b>• ВОПРОС № 3: ЗАПРЕЩЕНО ЛЕЧИТЬСЯ ЗАПРЕТНЫМ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Лечение при помощи запретного запрещено (харам)».</i>",{"mt":0.34}],["p","Исходя из хадиса, приводимого у Муслима<sup>4</sup> и других со слов Абу Хурайры о том, что пророк (да благословит его Аллах и приветствует) запретил скверные лекарства<sup>5</sup>."],["p","Абу Дауд (3874) привёл хадис со слов Абу ад-Дарды о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Поистине, Аллах ниспослал как болезнь, так и излечение, и Он дал исцеление от каждой болезни. Поэтому лечитесь, но не лечитесь посредством запретного».</i></b> В иснаде этого хадиса присутствует Исма′иль ибн ‘Аййаш<sup>6</sup>."],["p","Также достоверно известно, что пророк (да благословит его Аллах и приветствует) запретил лечиться посредством алкоголя, как это приводится у Муслима (1984) и в других сборниках."],["p","Также в сборнике у аль-Бухари (5614) сообщается, что Ибн Мас‘уд сказал: <i>«Поистине, Аллах не сделал для вас излечение в том, что Он запретил вам».</i>"],["p","Большинство учёных сошлось на запрете лечения посредством нечистот и алкоголя."]],"notes":[[4,"Хадис достоверен, однако его нет в сборнике у Муслима."],[5,"Ахмад (8048), Абу Дауд (3870), ат-Тирмизи (2045), Ибн Маджа (3459)."],[6,"Хадис достоверный. См. «ат-Та‘ликату р-радыййа» (3/153)."]]},{"n":1084,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","К этому не имеет отношение то, что пророк (да благословит его Аллах и приветствует) дозволил лечиться верблюжьей мочой, как это приводится в Сахихе<sup>7</sup>, так как она не относится ни к нечистотам, ни к запретному. Но даже если допустить первоначальную запретность верблюжьей мочи, то и тогда по правилам объединения следует, что из области указания обобщённых текстов исключается область указания конкретизирующих текстов."],["p","Уалию-Ллах ад-Дахляуи в «аль-Мусаува шарх аль-Муватта» сказал: <i>«Учёные имели различные мнения относительно дозволенности применения нечистот в лечении, и большинство из них считало это дозволенным за исключением применения алкоголя. Доводом на это является то, что пророк (да благословит его Аллах и приветствует), дозволивший группе мужчин лечение верблюжьей мочой, в отношении алкоголя сказал:</i> <b><i>«Поистине, в нём нет лечения, напротив, в нём болезнь»<sup>8</sup>.</i></b>"],["p","<i>Другие же учёные считали запретным лечение нечистотами, исходя из запрета посланника Аллаха (да благословит его Аллах и приветствует) лечиться скверной<sup>9</sup>, где под скверной имеется в виду либо скверна нечистоты, либо это — скверность вкуса и наличие вероятности отравления».</i>"],["p","Также ад-Дахляуи в «аль-Худжа аль-балига» говорит: <i>«Исключением из дозволенного являются: лечение посредством алкоголя, так как в нём присутствует зло, которое его не покидает; лечение посредством скверны — т. е. яда, при наличии альтернативы — так как есть опасение за жизнь; а также лечение посредством прижигания, при наличии альтернативы, так как прижигание огнём является одной из причин того, что ангелы покидают это место».</i>"],["p","Этот вопрос я подробно разобрал в своей книге «Далилю т-талиб ‘аля арджахи ль-маталиб»."],["h","<b>• ВОПРОС № 4: ПОЛОЖЕНИЕ ПРИЖИГАНИЯ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Прижигание является нежелательным».</i>",{"mt":0.34}]],"notes":[[7,"Аль-Бухари (3018), Муслим (1671)."],[8,"Муслим (1984)."],[9,"Ахмад (8048), Абу Дауд (3870)."]]},{"n":1085,"head":"КНИГА 17. МЕДИЦИНА","side":"r","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","Исходя из хадиса, приводимого аль-Бухари и другими со слов Ибн ‘Аббаса о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Лечение заключается в трёх вещах: в надрезах цирюльника (при кровопускании), в употреблении мёда и в прижигании огнём, и я запрещаю своей общине прижигание огнём»<sup>10</sup>.</i> </b>В другой версии хадиса говорится: <b><i>«…но мне не нравится прижигание огнём»<sup>11</sup>.</i></b>"],["p","Ахмад (4/427), Абу Дауд (3865), Ибн Маджа (3490) и ат-Тирмизи (2049), подтвердивший его достоверность, привели хадис со слов ‘Имрана ибн Хусайна, который сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) запретил нам прижигание, и когда мы делали его, оно не приводило к успеху и избавлению».</i>"],["p","Также пришли доводы на то, что запрет на прижигание указывает на нежелательность, а не на запретность, как например хадис, приводимый у Муслима (2208) и у других со слов Джабира о том, что пророк (да благословит его Аллах и приветствует) дважды делал прижигание руки Са‘да ибн Му‘аза."],["p","Также ат-Тирмизи (2050), подтверждая его достоверность, привёл хадис со слов Анаса о том, что посланник Аллаха (да благословит его Аллах и приветствует) сделал прижигание Са‘ду ибн Зураре от его болезни."],["p","Причина нежелательности прижигания заключается в том, что нём присутствует причинение страданий посредством огня, а известно, что никто не имеет права причинять страдания огнём, кроме Господа огня. Также были названы и другие причины нежелательности этого, а учёные объединяли между этими хадисами, совмещая их различными способами."],["h","<b>• ВОПРОС № 5: УЗАКОНЕННОСТЬ КРОВОПУСКАНИЯ</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«И нет проблем в кровопускании».</i>",{"mt":0.34}],["p","Исходя из хадиса, приводимого в обоих Сахихах и других сборниках со слов Джабира о том, что он слышал, как посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Если и есть</i></b>"]],"notes":[[10,"Аль-Бухари (5680)."],[11,"Аль-Бухари (5683), Муслим (2205)."]]},{"n":1086,"head":"ЖЕМЧУЖИНА ФИКХА","side":"l","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.48,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["c","<b><i>польза в чём-либо из ваших методов лечения, то в кровопускании, в употреблении мёда и в прижигании, если это лечение будет соответствовать болезни, но мне не нравится прижигание»<sup>12</sup>.</i></b>"],["p","Ранее уже приводился точно такой же хадис со слов Ибн ‘Аббаса<sup>13</sup>."],["p","Абу Дауд (3860) и ат-Тирмизи (2051) привели хадис с достоверным иснадом со слов Анаса, который сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) делал кровопускание на боковые затылочные вены (ахда‘ан) и между лопаток (кахиль). И он делал кровопускание семнадцатого, девятнадцатого и двадцать первого числа (лунного) месяца».</i>"],["p","Также Абу Дауд (3861) привёл хадис с приемлемым иснадом со слов Абу Хурайры о том, что посланник Аллаха (да благословит его Аллах и приветствует) сказал: <b><i>«Кто сделает кровопускание 17, 19 или 21-го числа, это станет для него исцелением от всех болезней»<sup>14</sup>.</i></b>"],["p","По данной теме есть и другие хадисы, которые включают в себя упоминание тех или иных дней, в которые предпочтительнее делать кровопускание. И цель данной главы лишь в приведении доводов на дозволенность кровопускания."],["p","И этого же придерживаются все мусульмане."],["h","<b>• ВОПРОС № 6: УЗАКОНЕННОСТЬ ЗАГОВОРОВ</b>",{"mt":0.3,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«Также нет проблем в заговорах (рукья)…».</i>",{"mt":0.34}],["p","Заклинание — это произнесение определённых слов, имеющих влияние и зарекомендовавших себя результатами. При этом они не должны противоречить основам религии, содержа в себе многобожие. Лучше, если они будут из Корана и Сунны или того, что похоже на это из смиренного обращения к Всевышнему Аллаху. А хадисы, в которых пришёл запрет на заговоры, амулеты и привороты относятся к тому, что содержит многобожие или же полное упование на причины до такой степени, что забывают о Всевышнем Создателе."]],"notes":[[12,"Аль-Бухари (5683), Муслим (2205–71)."],[13,"Аль-Бухари (5680)."],[14,"Хадис достоверный. См. ан-Навави «Аль-маджму‘» (9/62), аль-Альбани «Сахих аль-Джами‘» (5968)."]]},{"n":1087,"head":"КНИГА 17. МЕДИЦИНА","side":"r","frames":[{"s":"a","h":28.9,"mt":0.91,"pb":0.47,"ml":-3,"mr":-3,"pl":8,"pr":8}],"blocks":[["p","Уалию-Ллах ад-Дахляуи в «аль-Мусаува шарх аль-Муватта» сказал: <i>«Хадисы относительно чтения заговоров различны и касаются различных ситуаций. Те из них, в которых приходит запрет, касаются заговоров, содержащих многобожие, упоминание шайтанов или же они произносятся не на арабском языке так, что непонятно, о чём в них говорится, и не исключается возможность содержания в них колдовства или слов неверия. А узаконенными и желательными заговорами являются содержащие в себе Коран и поминание Аллаха.</i>"],["p","Также заговоры различаются по видам. Есть такие, которые передаются от праведных предшественников. Так, сообщается, что ‘Аиша не видела проблем в том, чтобы читать на воду поплёвывая в неё, а затем эту воду использовать в лечении больного."],["p","Муджахид сказал: «Нет проблем в том, чтобы написать что-то из Корана, затем смыть это и этой водой напоить больного»."],["p","А Ибн ‘Аббас повелел человеку, чтобы он написал для своей тяжело рожающей жены два аята из Корана и некоторые слова, затем смыл их и напоил жену."],["p","Также, когда Са‘ид ибн аль-Мусайиб был спрошен о маленьких листочках, на которых пишут Коран и вешают на женщин и детей, сказал, что нет в этом проблем, если их будут помещать в серебряную или кожаную оболочку, и повесят на шею»."],["h","<b>• ВОПРОС № 7: ЗАГОВОР ОТ СГЛАЗА</b>",{"mt":0.31,"fr":1}],["p","[Сказал аш-Шаукани]: <i>«…которые читаются, как от сглаза, так и от чего-то другого».</i>",{"mt":0.34}],["p","Исходя из хадиса, приводимого у Муслима (2196) и у других со слов Анаса, который сказал: <i>«Посланник Аллаха (да благословит его Аллах и приветствует) дозволил читать заговоры от сглаза, жара и муравья».</i>"],["p","Под жаром в данном случае имеется в виду последствия укуса ядовитых животных и насекомых, а под муравьём — раны от трипаносомоза."],["p","Муслим (2200) и другие привели также хадис со слов ‘Ауфа ибн Малика, который сказал: <i>«Мы читали заговоры во времена доисламской джахилии, и когда мы спросили о них пророка (да благословит его</i>"]],"notes":[]}];
